  "tm.guide.title": "Jak na to",
  "tm.guide.show": "Jak na to?",
  "tm.guide.hide": "Skrýt nápovědu",
  "tm.guide.paths.1": "Začněte cestou nahoře – je seřazená podle dopadu × pravděpodobnosti.",
  "tm.guide.paths.2": "V „Proč je cesta schůdná“ ověřte kroky. Když je cesta reálná, založte riziko; jinak ji akceptujte se zdůvodněním (např. opatření mimo CONTIX).",
  "tm.guide.paths.3": "Opravy plánujte u úzkých hrdel – jedna oprava přeruší více cest. Po opravě se cesta při dalším načtení sama změní nebo zmizí.",
  "tm.guide.paths.terms": "Snadnost kroku = odhad z doložených slabin (KEV, kritická zranitelnost, chybějící EDR, MFA, segmentace). Pravděpodobnost cesty = součin snadností. Korunní klenot = kritické nebo důležité primární aktivum.",
  "tm.guide.calibration.1": "Nahoře jsou neohodnocená rizika a rizika s největší odchylkou od dat.",
  "tm.guide.calibration.2": "Rozbalte „Podklady“ – každý návrh má zdůvodnění (BIA, incidenty, opatření). Nesedí-li data, opravte je u zdroje.",
  "tm.guide.calibration.3": "„Použít“ uloží hodnocení do historie přehodnocení. Návrh je vodítko – s jinou znalostí rozhodněte jinak přímo v riziku.",
  "tm.guide.calibration.terms": "Rozdíl +1 = data ukazují vyšší hodnotu než současné hodnocení. Jistota roste s počtem zdrojů dat (BIA, incidenty, alerty, opatření, zranitelnosti).",
  "tm.guide.landscape.1": "Zadejte odvětví společnosti – bez něj se úroveň hrozby scénářů nemění.",
  "tm.guide.landscape.2": "Projděte aktéry s vysokou a střední relevancí; podle vlastní znalosti je potvrďte nebo vylučte se zdůvodněním.",
  "tm.guide.landscape.3": "Slepá místa detekce u technik relevantních aktérů předejte SOC jako náměty na pravidla nebo hledání hrozeb.",
  "tm.guide.landscape.terms": "Relevance = odvětví + zmínky NÚKIB / CERT + indikátory MISP + techniky v SOC. Katalog aktérů je orientační.",
  "tm.guide.models.1": "Založte model pro aplikaci nebo projekt; u aplikace zaškrtněte předvyplnění z grafu aktiv.",
  "tm.guide.models.2": "V „Prvky a toky“ doplňte zóny, citlivost dat, ověření a šifrování – podle nich se určí hrozby a závažnost.",
  "tm.guide.models.3": "V „Hrozby“ rozhodněte každou hrozbu; „Výstupy“ dají bezpečnostní požadavky a zprávu ve Wordu.",
  "tm.guide.models.terms": "STRIDE = podvržení identity, změna dat, popření, únik informací, odepření služby, zvýšení oprávnění. Tok mezi zónami = hranice důvěry (vyšší závažnost).",
