  "tour.compliancePath.title": "Cesta k souladu",
  "tour.compliancePath.text": "Stav všech oblastí a další doporučený krok. Na stránkách modulů je panel Jak postupovat – určete u něj garanta a další krok mu přijde do Moje práce. Tlačítko Příprava na audit vytvoří podklady pro auditora.",
  "gd.starter.policyVersion": "Osnova ze startovacího balíčku",
  "gd.starter.policyContent": "# Bezpečnostní politika\n\n> Koncept ze startovacího balíčku CONTIX. Hlavní předpis: {fw}. Doplňte text každé kapitoly, ověřte soulad s předpisem a předložte ke schválení vrcholným vedením.\n\n## 1. Účel a rozsah\nProč politika vzniká, na které služby, procesy, lokality a společnosti se vztahuje.\n\n## 2. Závazek vrcholného vedení\nPodpora ISMS, zajištění zdrojů, schvalování politiky a pravidelné přezkoumání.\n\n## 3. Cíle bezpečnosti informací\nOdkaz na cíle ISMS, jejich měření a vyhodnocování.\n\n## 4. Role a odpovědnosti\nVrcholné vedení, manažer kybernetické bezpečnosti, vlastníci aktiv, procesů a rizik, uživatelé, dodavatelé.\n\n## 5. Řízení rizik\nMetodika, akceptovatelná úroveň rizika, plán zvládání a pravidelné přehodnocení.\n\n## 6. Zásady bezpečnosti\n- Řízení aktiv a klasifikace informací\n- Řízení přístupu a identit (včetně vícefaktorového ověření)\n- Bezpečnost lidských zdrojů a povědomí\n- Řízení dodavatelů\n- Zvládání událostí a incidentů a jejich hlášení\n- Kontinuita činností a zálohování\n- Řízení zranitelností, změn, vývoje a údržby\n- Bezpečnost sítí, kryptografie, zaznamenávání a detekce událostí\n- Fyzická bezpečnost\n\n## 7. Výjimky\nKdo výjimku schvaluje, na jak dlouho a s jakými kompenzačními opatřeními.\n\n## 8. Kontrola, audit a přezkum\nAudity kybernetické bezpečnosti, vyhodnocení účinnosti ISMS a přezkum politiky alespoň jednou ročně.\n\n## 9. Související dokumenty\nSměrnice a postupy, které politiku rozpracovávají.\n",
  "srv.ops.restore.label": "Test obnovy",
  "srv.ops.restore.none": "Žádný zaznamenaný test obnovy – v Administrace → Provoz klikněte na „Zálohovat a otestovat obnovu“, nebo na serveru spusťte: cd /opt/contix && sudo docker compose --profile full run --rm backup restore.sh --test (otestuje nejnovější zálohu; opakujte aspoň jednou za {days} dní).",
